INSERT INTO dump_descriptions (base_key, description) VALUES ('displayevents', 'Adds a customizable HUD strip for cave events and collectibles, with icon, orientation, position, scale, and opacity controls.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('expautocannon_p', 'Adds experimental Autocannon upgrades and overclocks, narrows its base spread, and removes the weapon''s direct-hit stagger duration.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
